```c
int largo, ancho, n, contador;
float area, total;
total = 0;
contador = 0;
printf("Cuantas parcelas? ");
scanf("%d", &n);
area = largo * ancho;   // <-- aquí calcula el área
while (contador < n) {
    printf("Largo: "); scanf("%d", &largo);
    printf("Ancho: "); scanf("%d", &ancho);
    total = total + area;
    contador++;
